            return step_toward(self_pos, tp)
        enemy = observation.get("opponent_position")
        if enemy is not None:
            return step_toward(self_pos, pos(enemy, self_pos))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    resource = best_by(resources, lambda c: dist(pos(c, self_pos), self_pos), None)
    if resource is not None:
        rp = pos(resource, self_pos)
        return step_toward(self_pos, rp)

    enemies = observation.get("opponents") or observation.get("enemy_positions") or []
    enemy = best_by(enemies, lambda c: dist(pos(c, self_pos), self_pos), None)
    if enemy is not None:
        ep = pos(enemy, self_pos)
        return step_away(self_pos, ep)

    if env == "resource_collection":
        return step_toward(self_pos, opp_pos)

    return [0, 0]

